from .repository import (
    put_contact,
    get_contact_name,
    insert_contact,
    update_contact_name,
)

def add_contact(connection, email, name):
    with connection:
        put_contact(connection, email, name)

def _validate_batch(rows):
    if not isinstance(rows, list):
        raise ValueError("rows must be a list of contact objects")
    contacts = []
    seen = set()
    for row in rows:
        if not isinstance(row, dict):
            raise ValueError("each row must be an object")
        if set(row) != {"email", "name"}:
            raise ValueError("each row must have exactly email and name fields")
        email = row["email"]
        name = row["name"]
        if not isinstance(email, str) or not isinstance(name, str):
            raise ValueError("email and name must be strings")
        email = email.strip()
        name = name.strip()
        if email.count("@") != 1:
            raise ValueError("email must contain exactly one @")
        local, domain = email.split("@")
        if not local or not domain:
            raise ValueError("email must have nonempty sides")
        if any(char.isspace() for char in email):
            raise ValueError("email must not contain whitespace")
        email = email.lower()
        if not name:
            raise ValueError("name must be nonempty")
        if email in seen:
            raise ValueError("duplicate email in batch")
        seen.add(email)
        contacts.append((email, name))
    return contacts

def import_contacts(connection, rows):
    contacts = _validate_batch(rows)
    inserted = 0
    updated = 0
    with connection:
        for email, name in contacts:
            if get_contact_name(connection, email) is None:
                insert_contact(connection, email, name)
                inserted += 1
            else:
                update_contact_name(connection, email, name)
                updated += 1
    return {"inserted": inserted, "updated": updated}
